package com.veyra.admin;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/admin/config")@PreAuthorize("hasRole('ADMIN')")public class ConfigController{private final JdbcTemplate db;public ConfigController(JdbcTemplate d){db=d;}public record Commission(int bps){}
 @PostMapping("/commission/standard")void standard(@RequestBody Commission c){if(c.bps()<0||c.bps()>3000)throw new IllegalArgumentException();Integer v=db.queryForObject("select coalesce(max(version_no),0)+1 from commission_policy_versions where scope_type='STANDARD'",Integer.class);db.update("update commission_policy_versions set status='INACTIVE',effective_to=now() where scope_type='STANDARD' and status='ACTIVE'");db.update("insert into commission_policy_versions(id,scope_type,commission_bps,version_no,status,effective_from) values (gen_random_uuid(),'STANDARD',?,?,'ACTIVE',now())",c.bps(),v);}
 @PostMapping("/commission/partner/{partnerId}")void partner(@PathVariable UUID partnerId,@RequestBody Commission c){if(c.bps()<0||c.bps()>3000)throw new IllegalArgumentException();Integer v=db.queryForObject("select coalesce(max(version_no),0)+1 from commission_policy_versions where scope_type='PARTNER' and partner_id=?",Integer.class,partnerId);db.update("update commission_policy_versions set status='INACTIVE',effective_to=now() where scope_type='PARTNER' and partner_id=? and status='ACTIVE'",partnerId);db.update("insert into commission_policy_versions(id,scope_type,partner_id,commission_bps,version_no,status,effective_from) values (gen_random_uuid(),'PARTNER',?,?,?,'ACTIVE',now())",partnerId,c.bps(),v);}
}